package com.nuvio.tv.core.subtitlelibrary

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class AssFontNamesTest {
    private val v4Plus = """
        [Script Info]
        ; Script generated by Aegisub
        ScriptType: v4.00+

        [V4+ Styles]
        Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold
        Style: Default,Open Sans Semibold,52,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0
        Style: Signs,@Vertical Gothic,40,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0

        [Events]
        Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
        Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,{\fnGandhi Sans\b1}Hola, mundo{\fn}normal
        Dialogue: 0,0:00:03.00,0:00:04.00,Signs,,0,0,0,,{\pos(10,10)\fn Komika Axis \fs20}Cartel
        Comment: 0,0:00:05.00,0:00:06.00,Default,,0,0,0,,{\fnOnly In Comment}nada
    """.trimIndent()

    @Test
    fun `styles and fn overrides in V4+ scripts`() {
        assertEquals(
            setOf("open sans semibold", "vertical gothic", "gandhi sans", "komika axis"),
            AssFontNames.usedFontNames(v4Plus)
        )
    }

    @Test
    fun `V4 styles with the Fontname column in another place`() {
        val script = """
            [V4 Styles]
            Format: Fontname, Name, Fontsize
            Style: Trebuchet MS,Default,30
            [Events]
            Format: Marked, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
            Dialogue: Marked=0,0:00:01.00,0:00:02.00,Default,,0,0,0,,texto, con, comas{\fnArial Black}x
        """.trimIndent()
        assertEquals(setOf("trebuchet ms", "arial black"), AssFontNames.usedFontNames(script))
    }

    @Test
    fun `an empty fn adds nothing and several overrides in one block are read`() {
        val names = mutableSetOf<String>()
        AssFontNames.overrideFontNames("{\\fn\\i1}a{\\fnA\\bord2\\fnB}b", names)
        assertEquals(setOf("a", "b"), names)
    }

    @Test
    fun `BOM, CRLF and UTF-16 are decoded`() {
        val crlf = v4Plus.replace("\n", "\r\n")
        val utf8Bom = byteArrayOf(0xEF.toByte(), 0xBB.toByte(), 0xBF.toByte()) + crlf.toByteArray(Charsets.UTF_8)
        val utf16le = byteArrayOf(0xFF.toByte(), 0xFE.toByte()) + crlf.toByteArray(Charsets.UTF_16LE)
        val utf16beNoBom = crlf.toByteArray(Charsets.UTF_16BE)
        val expected = AssFontNames.usedFontNames(v4Plus)
        assertEquals(expected, AssFontNames.usedFontNames(utf8Bom))
        assertEquals(expected, AssFontNames.usedFontNames(utf16le))
        assertEquals(expected, AssFontNames.usedFontNames(utf16beNoBom))
    }

    @Test
    fun `embedded Fonts section and comments do not add names`() {
        val script = v4Plus + "\n[Fonts]\nfontname: Embedded_0.ttf\nM3)1;1D)1,\n"
        assertTrue("embedded_0.ttf" !in AssFontNames.usedFontNames(script))
        assertTrue("only in comment" !in AssFontNames.usedFontNames(script))
    }
}
